INSERT INTO public.marketplace_capture_insights (id, "userId", "tenantId", "captureId", "productId", platform, "sourceUrl", "insightType", provider, status, "schemaVersion", "payloadHash", "idempotencyKey", "parentInsightIdsJson", "payloadJson", "rawCaptureJson", "rawCaptureIncluded", "storytellingReadiness", "claimResolutionsJson", "extensionVersion", "insightCreatedAt", "createdAt", "updatedAt") VALUES ('ins_08870ad124197cd81f88c513f0a74c59', 1, 'tenant-ZCSKEM9s', NULL, NULL, 'shopee', 'https://shopee.co.th/product/988318952/29301171259', 'product_brief', 'server_ai', 'ready', '1.0', '8aa20c4451a850021489337c10eb23947b2e584f4a7d8752f53be34872363019', 'shopee:8aa20c4451a850021489337c10eb23947b2e584f4a7d8752f53be34872363019:product_brief:server_ai', '[]', '{"source": {"url": "https://shopee.co.th/product/988318952/29301171259", "platform": "shopee"}, "category": "อุปกรณ์ตกแต่งผนัง", "confidence": 0.55, "evidenceIds": ["title:product", "price:current", "rating:score", "metric:sold", "description:product", "seller_info:shop", "image:1", "image:2", "image:3", "review:1", "review:2", "review:3"], "productName": "🔥[ราคาสุดคุ้ม ถูกที่สุด]🔥 ติดขอบผนัง ตกแต่งสวยงาม วอลเปเปอร์ลายกระเบื้อง วอลเปเปอร์ติดผนังลายต่าง วอลเปเปอร์", "shortSummary": "ยี่ห้อ: hoptech ชื่อสินค้า: ติดขอบผนัง ✅อ่านรายละเอียดก่อนกดสั่งสินค้า✅ รายละเอียดสินค้า: 1: สินค้านั้นทำจากโฟมสามมิติที่อ่อนนุ่ม, ป้องกันการชนกันของเด็ก, มีคุณสมบัติป้องกันการเปรอะเปื้อนและฉนวนกันเสียง 2: สติกเกอร์ติดผนังทำจากโฟมนุ่มที่มีความหนาแน่นสูง และทำจากวัสดุ XPE คุณภาพสูง 3.เป็นฉนวนกันเสียง กันความร้อน กันการชนที่รุนแรง กันน้ำ พื้นผิวนั้นสามารถเช็ดถูได้ 4: การออกแบบ การติดนั้นทำได้ง่ายๆ จะติดทั้งแผ่นเลย หรือ จะแบ่งตัดเป็นชิ้นแล้วนำไปติดก็ได้ ง่ายมากๆ 5.[ขนาด]: กว้าง5 ซม. * สูง230ซม. และขนาด กว้าง 8 cm ยาว 230 cm ในการตัดนั้น ด้านซ้ายหรือด้านขวานั้นจะไม่เท่ากัน อาจขาดไป 1ซม.โดยประมาณไป 6. วิธีการติดตั้ง: สินค้าเรานั้นเป็นแบบมีกาวในตัวพร้อมอยู่แล้ว การติดนั้นง่ายมากแค่ลอกแผ่นด้านหลังออกแล้วติดได้เลย ไม่จำเป็นต้องไปซื้อกาวมาติดเพิ